import numpy as np,cv2
from scipy.ndimage import distance_transform_edt
names=['oblique','left_vertical','dot','upper_horizontal','short_horizontal','middle_hook','lower_loop','flourish']
truth=np.load('/app/output/target_mask.npy')
labels=np.load('/app/output/target_labels.npy')
ms=[np.load(f'/app/output/stroke_{i}.npy') for i in range(8)]
comps=[int(labels[int({'oblique':305,'left_vertical':448,'dot':244,'upper_horizontal':385,'short_horizontal':471,'middle_hook':555,'lower_loop':596,'flourish':743}[n]), int({'oblique':443,'left_vertical':389,'dot':619,'upper_horizontal':492,'short_horizontal':560,'middle_hook':524,'lower_loop':548,'flourish':701}[n])]) for n in names]
print('components',comps)
def morph(m,r):
 if r==0:return m
 if r>0:return cv2.dilate(m.astype('uint8'),np.ones((2*r+1,2*r+1),np.uint8)).astype(bool)
 return cv2.erode(m.astype('uint8'),np.ones((2*(-r)+1,2*(-r)+1),np.uint8)).astype(bool)
def shift(m,dx,dy):
 M=np.float32([[1,0,dx],[0,1,dy]])
 return cv2.warpAffine(m.astype('uint8'),M,(1024,1024),flags=cv2.INTER_NEAREST,borderValue=0).astype(bool)
def score(pr,t):
 inter=np.logical_and(pr,t).sum();union=np.logical_or(pr,t).sum()
 return inter/max(union,1),inter/max(pr.sum(),1),inter/max(t.sum(),1)
# isolated comps
for i in range(5):
 t=labels==comps[i]
 best=(-1,None)
 for r in range(-8,9):
  base=morph(ms[i],r)
  for dy in range(-35,36,1):
   for dx in range(-35,36,1):
    x=score(shift(base,dx,dy),t)[0]
    if x>best[0]:best=(x,(dx,dy,r,score(shift(base,dx,dy),t)))
 print(names[i], 'area',t.sum(),ms[i].sum(),'best',best)
# Composite lower component coordinate descent
T=labels==comps[5]
cur=[(0,0,0) for _ in range(3)]
for it in range(3):
 for jj,i in enumerate([5,6,7]):
  best=(-1,None)
  others=np.zeros_like(T)
  for kk,ii in enumerate([5,6,7]):
   if kk!=jj:
    dx,dy,r=cur[kk]; others|=shift(morph(ms[ii],r),dx,dy)
  for r in range(-6,10):
   base=morph(ms[i],r)
   for dy in range(-30,31):
    for dx in range(-30,31):
     p=others|shift(base,dx,dy)
     z=score(p,T)
     if z[0]>best[0]: best=(z[0],(dx,dy,r,z))
  cur[jj]=best[1][:3]
  print('iter',it,names[i],cur[jj],best[1][3])
p=np.zeros_like(T)
for i,(dx,dy,r) in zip([5,6,7],cur):p|=shift(morph(ms[i],r),dx,dy)
print('lower total',score(p,T),p.sum(),T.sum())
# global composite (each comp except overlap lower)
pred=np.zeros_like(truth)
for i in range(5):
 dx,dy,r=[0,0,0] # placeholders later
 pred|=ms[i]
for i,(dx,dy,r) in zip([5,6,7],cur):pred|=shift(morph(ms[i],r),dx,dy)
