import cv2,numpy as np,time
T=np.load('/app/output/target_mask.npy').astype(bool);L=np.load('/app/output/target_labels.npy')
ms=[np.load(f'/app/output/stroke_{i}.npy').astype(bool) for i in range(9)]
D=cv2.distanceTransform((~T).astype('uint8'),cv2.DIST_L2,5)
F=(~T)&(D>4.5);TS=T.sum();
def bbox(m):
 y,x=np.where(m);return x.min(),y.min(),x.max()+1,y.max()+1
def evaluate(i, others, cand, roi, lam=1.0):
 y0,y1,x0,x1=roi; O=others[y0:y1,x0:x1]; T0=T[y0:y1,x0:x1];F0=F[y0:y1,x0:x1]
 op=others.sum();baseI=(T&others).sum();baseF=(F&others).sum()
 area=cand.sum(); over=(O&cand).sum(); hit=((T0&~O)&cand).sum();far=((F0&~O)&cand).sum()
 pred=op+area-over; inter=baseI+hit
 iou=inter/(TS+pred-inter)
 far_total=baseF+far
 return iou-lam*far_total/TS, iou, far_total/TS,inter/TS,pred
params=[(0,0,0) for _ in ms]
for iteration in range(2):
 for i,m in enumerate(ms):
  others=np.zeros_like(T)
  for j,n in enumerate(ms):
   if j==i:continue
   dx,dy,r=params[j]
   z=n.copy()
   if r>0:z=cv2.dilate(z.astype('uint8'),np.ones((2*r+1,2*r+1),np.uint8)).astype(bool)
   elif r<0:z=cv2.erode(z.astype('uint8'),np.ones((2*-r+1,2*-r+1),np.uint8)).astype(bool)
   M=np.float32([[1,0,dx],[0,1,dy]])
   others|=cv2.warpAffine(z.astype('uint8'),M,(1024,1024),flags=cv2.INTER_NEAREST).astype(bool)
  # ROI expanded 25px around mask bbox
  x0,y0,x1,y1=bbox(m); pad=24
  roi=(max(0,y0-pad),min(1024,y1+pad),max(0,x0-pad),min(1024,x1+pad))
  ry0,ry1,rx0,rx1=roi;orig=m[ry0:ry1,rx0:rx1]
  best=(-1,None)
  # dxy search
  for r in range(-3,5):
   if r>0:z=cv2.dilate(orig.astype('uint8'),np.ones((2*r+1,2*r+1),np.uint8)).astype(bool)
   elif r<0:z=cv2.erode(orig.astype('uint8'),np.ones((2*-r+1,2*-r+1),np.uint8)).astype(bool)
   else:z=orig
   for dy in range(-12,13):
    for dx in range(-12,13):
     c=cv2.warpAffine(z.astype('uint8'),np.float32([[1,0,dx],[0,1,dy]]),(rx1-rx0,ry1-ry0),flags=cv2.INTER_NEAREST).astype(bool)
     val=evaluate(i,others,c,roi,lam=1.1)
     if val[0]>best[0]:best=(val[0],(dx,dy,r,val))
  params[i]=best[1][:3]
  print('it',iteration,'stroke',i,'param',params[i],'metrics',best[1][3])
# overall transformed metrics
P=np.zeros_like(T)
for m,(dx,dy,r) in zip(ms,params):
 z=m.copy()
 if r>0:z=cv2.dilate(z.astype('uint8'),np.ones((2*r+1,2*r+1),np.uint8)).astype(bool)
 elif r<0:z=cv2.erode(z.astype('uint8'),np.ones((2*-r+1,2*-r+1),np.uint8)).astype(bool)
 P|=cv2.warpAffine(z.astype('uint8'),np.float32([[1,0,dx],[0,1,dy]]),(1024,1024),flags=cv2.INTER_NEAREST).astype(bool)
inter=(P&T).sum();iou=inter/(P.sum()+T.sum()-inter)
print('FINAL params',params,'iou',iou,'precision',inter/P.sum(),'recall',inter/T.sum(),'far',((P&F).sum()/T.sum()),'stray',((P&~T).sum()/T.sum()))
